$ErrorActionPreference = "Stop"

Write-Host ""
Write-Host "==========================================================" -ForegroundColor Cyan
Write-Host "  DOWNFORCE UI/UX & PERFORMANCE UPGRADE (PHASES 1 - 3)    " -ForegroundColor Cyan
Write-Host "==========================================================" -ForegroundColor Cyan

if (-not (Test-Path "package.json")) {
    Write-Error "Please run this script from the root of the DOWNFORCE project (where package.json is located)."
    exit 1
}

function Write-Utf8File([string]$RelPath, [string]$Base64Payload) {
    $FullPath = Join-Path (Get-Location) $RelPath
    $Dir = Split-Path $FullPath -Parent
    if (-not (Test-Path $Dir)) {
        New-Item -ItemType Directory -Path $Dir -Force | Out-Null
    }
    $Bytes = [System.Convert]::FromBase64String($Base64Payload)
    [System.IO.File]::WriteAllBytes($FullPath, $Bytes)
    Write-Host ("  [OK] Updated " + $RelPath) -ForegroundColor Green
}

